            private void AddEventHandlerGenerated(object obj, XamlEventIndex eventIndex, object handler, bool handledEventsToo)
            {
                switch (eventIndex)
                {
                    default:
                        throw new ArgumentOutOfRangeException(nameof(eventIndex));
                }
            }
        
            private void AddEventHandlerGenerated(object obj, XamlEventIndex eventIndex, object handler)
            {
                switch (eventIndex)
                {
                    case XamlEventIndex.FrameworkElement_DataContextChanged:
                        AddFrameworkElement_DataContextChanged(obj, handler);
                        break;
                    case XamlEventIndex.FrameworkElement_SizeChanged:
                        AddFrameworkElement_SizeChanged(obj, handler);
                        break;
                    case XamlEventIndex.FrameworkElement_LayoutUpdated:
                        AddFrameworkElement_LayoutUpdated(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_KeyUp:
                        AddUIElement_KeyUp(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_KeyDown:
                        AddUIElement_KeyDown(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_GotFocus:
                        AddUIElement_GotFocus(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_LostFocus:
                        AddUIElement_LostFocus(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_DragStarting:
                        AddUIElement_DragStarting(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_DropCompleted:
                        AddUIElement_DropCompleted(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_CharacterReceived:
                        AddUIElement_CharacterReceived(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_DragEnter:
                        AddUIElement_DragEnter(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_DragLeave:
                        AddUIElement_DragLeave(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_DragOver:
                        AddUIElement_DragOver(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_Drop:
                        AddUIElement_Drop(obj, handler);
                        break;
                    case XamlEventIndex.UIElement_PointerPressed:
